@Test
public void testSync() throws Exception {
    project.setProperty("ivy.dep.file", "test/repositories/1/org6/mod6.2/ivys/ivy-0.4.xml");
    retrieve.setSync(true);
    File[] old = new File[] { new File(IvyPatternHelper.substitute(RETRIEVE_PATTERN, "org6", "mod6.1", "0.4", "mod6.1", "jar", "jar", // unknown configuration
    "unknown")), new File(IvyPatternHelper.substitute(RETRIEVE_PATTERN, "org6", "mod6.1", "0.4", "mod6.1", "unknown", "unknown", // unknown type
    "default")), new File(IvyPatternHelper.substitute(RETRIEVE_PATTERN, "org6", "mod6.1", "0.4", "unknown", "jar", "jar", // unknown artifact
    "default")), new File(IvyPatternHelper.substitute(RETRIEVE_PATTERN, "org6", "mod6.1", "unknown", "mod6.1", "jar", "jar", // unknown revision
    "default")) };
    for (File of : old) {
        touch(of);
    }
    retrieve.execute();
    assertTrue(new File(IvyPatternHelper.substitute(RETRIEVE_PATTERN, "org6", "mod6.1", "0.4", "mod6.1", "jar", "jar", "default")).exists());
    assertTrue(new File(IvyPatternHelper.substitute(RETRIEVE_PATTERN, "org6", "mod6.1", "0.4", "mod6.1", "jar", "jar", "extension")).exists());
    assertTrue(new File(IvyPatternHelper.substitute(RETRIEVE_PATTERN, "org1", "mod1.2", "2.1", "mod1.2", "jar", "jar", "extension")).exists());
    for (File of : old) {
        assertFalse(of + " should have been deleted by sync", of.exists());
    }
    // even conf directory should
    assertFalse(new File("build/test/lib/unknown").exists());
    // have been deleted
}

