@Test
public void testSyncWithIvyPattern() throws Exception {
    project.setProperty("ivy.dep.file", "test/repositories/1/org6/mod6.2/ivys/ivy-0.4.xml");
    String ivyPattern = "build/test/lib/[conf]/[organisation]/[module]/ivy-[revision].xml";
    retrieve.setIvypattern(ivyPattern);
    retrieve.setSync(true);
    File[] old = new File[] { new File(IvyPatternHelper.substitute(RETRIEVE_PATTERN, "org6", "mod6.1", "0.4", "mod6.1", "jar", "jar", // unknown configuration
    "unknown")), new File(IvyPatternHelper.substitute(RETRIEVE_PATTERN, "org6", "mod6.1", "0.4", "mod6.1", "unknown", "unknown", // unknown type
    "default")), new File(IvyPatternHelper.substitute(ivyPattern, "org6", "mod6.1", "0.4", "ivy", "ivy", "xml", // unknown conf for ivy
    "unk")), new File(IvyPatternHelper.substitute(ivyPattern, "unknown", "mod6.1", "0.4", "ivy", "ivy", "xml", // unknown organisation for ivy
    "default")) };
    for (File of : old) {
        touch(of);
    }
    retrieve.execute();
    assertTrue(new File(IvyPatternHelper.substitute(ivyPattern, "org6", "mod6.1", "0.4", "ivy", "ivy", "xml", "default")).exists());
    assertTrue(new File(IvyPatternHelper.substitute(ivyPattern, "org6", "mod6.1", "0.4", "ivy", "ivy", "xml", "extension")).exists());
    assertFalse(new File(IvyPatternHelper.substitute(ivyPattern, "org1", "mod1.2", "2.1", "ivy", "ivy", "xml", "extension")).exists());
    for (File of : old) {
        assertFalse(of + " should have been deleted by sync", of.exists());
    }
    assertFalse(new File("build/test/lib/unknown").exists());
    assertFalse(new File("build/test/lib/unk").exists());
    assertFalse(new File("build/test/lib/default/unknown").exists());
}

