    assertEquals(crp.getDependency(mod21), null);
    assertEquals(crp.getDependency(mod22), null);
    crp = report.getConfigurationReport("B");
    assertEquals(crp.getDependency(mod12), null);
    assertTrue(crp.getDependency(mod21) != null);
    assertTrue(Arrays.asList(crp.getDependency(mod21).getConfigurations(crp.getConfiguration())).containsAll(Collections.singletonList("A")));
    assertTrue(crp.getDependency(mod22) != null);
    assertTrue(Arrays.asList(crp.getDependency(mod22).getConfigurations(crp.getConfiguration())).containsAll(Collections.singletonList("myconf1")));
    crp = report.getConfigurationReport("C");
    assertEquals(crp.getDependency(mod12), null);
    assertTrue(crp.getDependency(mod21) != null);
    assertTrue(Arrays.asList(crp.getDependency(mod21).getConfigurations(crp.getConfiguration())).containsAll(Collections.singletonList("A")));
    assertTrue(crp.getDependency(mod22) != null);
    assertTrue(Arrays.asList(crp.getDependency(mod22).getConfigurations(crp.getConfiguration())).containsAll(Arrays.asList("myconf1", "myconf2")));
}

