@Test
public void testTransformation() {
    MRIDTransformationRule r = new MRIDTransformationRule();
    r.addSrc(new MRIDRule("apache", "commons.+", null));
    r.addDest(new MRIDRule("$m0", "$m0", null));
    assertEquals(ModuleRevisionId.newInstance("commons-client", "commons-client", "1.0"), r.transform(ModuleRevisionId.newInstance("apache", "commons-client", "1.0")));
    assertEquals(ModuleRevisionId.newInstance("apache", "module", "1.0"), r.transform(ModuleRevisionId.newInstance("apache", "module", "1.0")));
    r = new MRIDTransformationRule();
    r.addSrc(new MRIDRule(null, "commons\\-(.+)", null));
    r.addDest(new MRIDRule("$o0.commons", "$m1", null));
    assertEquals(ModuleRevisionId.newInstance("apache.commons", "client", "1.0"), r.transform(ModuleRevisionId.newInstance("apache", "commons-client", "1.0")));
    assertEquals(ModuleRevisionId.newInstance("apache", "module", "1.0"), r.transform(ModuleRevisionId.newInstance("apache", "module", "1.0")));
    r = new MRIDTransformationRule();
    r.addSrc(new MRIDRule("(.+)\\.(.+)", ".+", null));
    r.addDest(new MRIDRule("$o1", "$o2-$m0", null));
    assertEquals(ModuleRevisionId.newInstance("apache", "commons-client", "1.0"), r.transform(ModuleRevisionId.newInstance("apache.commons", "client", "1.0")));
    assertEquals(ModuleRevisionId.newInstance("apache", "module", "1.0"), r.transform(ModuleRevisionId.newInstance("apache", "module", "1.0")));
}

