        assertNotNull("Unexpected null value on VFS URI: " + resId, res);
        assertFalse("Resource does exist and it should not: " + resId, res.exists());
        // VFS apparently does some weird normalization so that resource id used to create
        // the VFS resource is not necessarily identical to the id returned from the getName
        // method <sigh>. We try to work around this by transforming things into java URIs.
        assertEquals("Failed on getName. Expected: " + resId + ". Actual: " + res.getName(), new URI(escapeUrl(resId)), new URI(escapeUrl(res.getName())).normalize());
        assertEquals("Expected null file modification date for URI: " + resId, 0, res.getLastModified());
        assertEquals("Expected zero file length for URI: " + resId, 0, res.getContentLength());
        assertFalse("Physical existence check returned true for non-existent resource: " + resId, res.physicallyExists());
    }
}

