    assertNotNull(dirs);
    assertEquals(4, dirs.size());
    List<URL> empty = lister.retrieveListing(ApacheURLListerTest.class.getResource("apache-dir-listing.html"), true, false);
    assertTrue(empty.isEmpty());
}

