/**
 * Tests that the {@link HttpClientHandler}, backed by
 * {@link CredentialsStore Ivy credentials store} works as expected when it interacts
 * with a HTTP server which requires authentication for accessing resources.
 *
 * @throws Exception if something goes wrong
 * @see <a href="https://issues.apache.org/jira/browse/IVY-1336">IVY-1336</a>
 */
@Test
public void testCredentials() throws Exception {
    // we catch it and check for presence of 401 in the exception message.
    // It's not exactly an contract that the IOException will have the 401 message
    // but for now that's how it's implemented and it's fine to check for the presence
    // of that message at the moment
    expExc.expect(IOException.class);
    expExc.expectMessage(endsWith("ivysettings.xml' 401 - 'Unauthorized"));
    final CredentialsStore credentialsStore = CredentialsStore.INSTANCE;
    final String realm = "test-http-client-handler-realm";
    final String host = "localhost";
    final Random random = new Random();
    final String userName = "test-http-user-" + random.nextInt();
    final String password = "pass-" + random.nextInt();
    credentialsStore.addCredentials(realm, host, userName, password);
    final InetSocketAddress serverBindAddr = new InetSocketAddress("localhost", TestHelper.getMaybeAvailablePort());
    final String contextRoot = "/testHttpClientHandler";
    final Path repoRoot = new File("test/repositories").toPath();
    assertTrue(repoRoot + " is not a directory", Files.isDirectory(repoRoot));
    // create a server backed by BASIC auth with the set of "allowed" credentials
    try (final AutoCloseable server = TestHelper.createBasicAuthHttpServerBackedRepo(serverBindAddr, contextRoot, repoRoot, realm, Collections.singletonMap(userName, password))) {
        final File target = new File(testDir, "downloaded.xml");
        assertFalse("File " + target + " already exists", target.exists());
        final URL src = new URL("http://localhost:" + serverBindAddr.getPort() + "/" + contextRoot + "/ivysettings.xml");
        // download it
        handler.download(src, target, null, defaultTimeoutConstraint);
        assertTrue("File " + target + " was not downloaded from " + src, target.isFile());
    }
    // now create a server backed by BASIC auth with a set of credentials that do *not* match
    // with what the Ivy credentials store will return for a given realm+host combination, i.e.
    // Ivy credential store will return back invalid credentials and the server will reject them
    try (final AutoCloseable server = TestHelper.createBasicAuthHttpServerBackedRepo(serverBindAddr, contextRoot, repoRoot, realm, Collections.singletonMap("other-" + userName, "other-" + password))) {
        final File target = new File(testDir, "should-not-have-been-downloaded.xml");
        assertFalse("File " + target + " already exists", target.exists());
        final URL src = new URL("http://localhost:" + serverBindAddr.getPort() + "/" + contextRoot + "/ivysettings.xml");
        // download it (expected to fail)
        handler.download(src, target, null, defaultTimeoutConstraint);
    }
}

/**
 * Tests that when {@link IvyAuthenticator} can't handle a authentication request and falls back
 * on an authenticator that was previously set, before IvyAuthenticator installed on top of it,
 * the other authenticator gets passed all the relevant requesting information, including the
 * {@link Authenticator#getRequestingURL() requesting URL} and
 * {@link Authenticator#getRequestorType() request type}
 *
 * @throws Exception if something goes wrong
 * @see <a href="https://issues.apache.org/jira/browse/IVY-1557">IVY-1557</a>
 */
@Test
public void testRequestURLAndType() throws Exception {
    testAuthenticator.expectedHost = "localhost";
    testAuthenticator.expectedPort = 12345;
    testAuthenticator.expectedPrompt = "Test prompt - testRequestURLAndType";
    testAuthenticator.expectedProtocol = "HTTP/1.1";
    testAuthenticator.expectedURL = new URL("http", "localhost", 12345, "/a/b/c");
    testAuthenticator.expectedType = Authenticator.RequestorType.PROXY;
    testAuthenticator.expectedScheme = "BASIC";
    testAuthenticator.expectedSite = InetAddress.getLoopbackAddress();
    // trigger the authentication
    final PasswordAuthentication auth = Authenticator.requestPasswordAuthentication(testAuthenticator.expectedHost, testAuthenticator.expectedSite, testAuthenticator.expectedPort, testAuthenticator.expectedProtocol, testAuthenticator.expectedPrompt, testAuthenticator.expectedScheme, testAuthenticator.expectedURL, testAuthenticator.expectedType);
    assertNotNull("Expected a password authentication, but got none", auth);
    assertEquals("Unexpected username", "dummy", auth.getUserName());
    assertTrue("Unexpected password", Arrays.equals("dummy".toCharArray(), auth.getPassword()));
}
